/root/schema_semantic_constrained_ie/outputs/docred_grammar_only.jsonl:676:{"doc_id": "Rambaan", "input_text": "Rambaan ( Rama 's Arrow ) is a 1948 Indian film with a mythological theme , directed by Vijay Bhatt . Made under the banner of Prakash Pictures , it had music by Shankar Rao Vyas . The story writer was Mohanlal Dave with dialogue by Pandit Girish . The film starred Shobhana Samarth , Prem Adib , Chandra Mohan , Umakant , Amirbai Karnataki and Raj Adib . Bhatt produced several films based on themes from the epic Ramayana , with Shobhana Samarth and Prem Adib . The films proved successful and included Bharat Milap ( 1942 ) , Ram Rajya ( 1943 ) and Rambaan . Shobhana Samarth as Sita and Prem Adib as Rama were extremely popular and accepted by the masses . Their success had them featuring as Rama and Sita on calendars . Chandra Mohan played the role of Ravana .", "gold_entities": [{"text": "Rama 's Arrow", "type": "MISC"}, {"text": "1948", "type": "TIME"}, {"text": "Indian", "type": "LOC"}, {"text": "Vijay Bhatt", "type": "PER"}, {"text": "Prakash Pictures", "type": "ORG"}, {"text": "Shankar Rao Vyas", "type": "PER"}, {"text": "Mohanlal Dave", "type": "PER"}, {"text": "Pandit Girish", "type": "PER"}, {"text": "Shobhana Samarth", "type": "PER"}, {"text": "Prem Adib", "type": "PER"}, {"text": "Chandra Mohan", "type": "PER"}, {"text": "Umakant", "type": "PER"}, {"text": "Amirbai Karnataki", "type": "PER"}, {"text": "Raj Adib", "type": "PER"}, {"text": "Bhatt", "type": "PER"}, {"text": "Ramayana", "type": "MISC"}, {"text": "Shobhana Samarth", "type": "MISC"}, {"text": "Prem Adib", "type": "MISC"}, {"text": "Bharat Milap", "type": "MISC"}, {"text": "1942", "type": "TIME"}, {"text": "Ram Rajya", "type": "MISC"}, {"text": "1943", "type": "TIME"}, {"text": "Sita", "type": "MISC"}, {"text": "Rama", "type": "MISC"}, {"text": "Ravana", "type": "PER"}], "gold_relations": [{"head": "Rama 's Arrow", "tail": "1948", "type": "P577", "head_type": "MISC", "tail_type": "TIME"}, 