/root/schema_semantic_constrained_ie/outputs/docred_grammar_only.jsonl:679:{"doc_id": "Joan Burton", "input_text": "Joan Burton ( born 1 February 1949 ) is an Irish Labour Party politician who served as Tánaiste and Leader of the Labour Party from 2014 to 2016 , Minister for Social Protection from 2011 to 2016 , Deputy Leader of the Labour Party from 2007 to 2014 , Minister of State at the Department of Foreign Affairs from 1994 to 1997 and Minister of State at the Department of Social Welfare 1993 to 1994 . She has been a Teachta Dála ( TD ) for the Dublin West constituency since 2002 , and previously from 1992 to 1997 . Burton was first elected to Dáil Éireann at the 1992 general election . From 1995 to 1997 , she was Minister of State at the Department of Foreign Affairs . She lost her seat at the 1997 general election , but was re - elected to the Dáil at the 2002 general election . She was deputy leader of the Labour Party under Eamon Gilmore , between 2007 and 2014 . She was Tánaiste ( Deputy Prime Minister ) from 2014 to 2016 and Minister for Social Protection from 2011 to 2016 . She resigned as Labour Party leader in May 2016 , following heavy losses by the party in the 2016 general election .", "gold_entities": [{"text": "Joan Burton", "type": "PER"}, {"text": "1 February 1949", "type": "TIME"}, {"text": "Irish Labour Party", "type": "ORG"}, {"text": "Labour Party", "type": "ORG"}, {"text": "2014", "type": "TIME"}, {"text": "2016", "type": "TIME"}, {"text": "2011", "type": "TIME"}, {"text": "2007", "type": "TIME"}, {"text": "Department of Foreign Affairs", "type": "ORG"}, {"text": "1994", "type": "TIME"}, {"text": "1997", "type": "TIME"}, {"text": "Department of Social Welfare", "type": "ORG"}, {"text": "1993", "type": "TIME"}, {"text": "Dublin West", "type": "LOC"}, {"text": "2002", "type": "TIME"}, {"text": "1992", "type": "TIME"}, {"text": "Dáil", "type": "ORG"}, {"text": "1995", "type": "TIME"}, {"text": "Eamon Gilmore", "type": "PER"}, {"text": "May 20