/root/schema_semantic_constrained_ie/outputs/docred_grammar_only.jsonl:680:{"doc_id": "Astana International Financial Centre", "input_text": "The Astana International Financial Centre ( AIFC ) is a financial hub in Astana , Kazakhstan that officially launched on July 5 , 2018 . On 20 May 2015 , the President of Republic of Kazakhstan Nursultan Nazarbayev announced the “ 100 Concrete Steps ” Plan of the Nation to implement the five institutional reforms , designed to provide a strong national platform needed to achieve country ’s ambition of joining the top 30 developed countries by 2050 . As part of the Plan of the Nation , the AIFC was established with a special legal status to be based on the EXPO-2017 International Specialized Exhibition infrastructure . The Constitutional Law \" On the Astana International Financial Centre \" approved on 7 December 2015 provides a legal framework for the functioning of the AIFC as well as a favourable environment for its participants . The Astana International Financial Centre plays one of the main roles in attracting financial resources . It is positioned as a financial hub for the countries of Central Asia , the Caucasus , Eurasian Economic Union ( EAEU ) , Middle East , Western China , Mongolia and Europe .", "gold_entities": [{"text": "Astana International Financial Centre", "type": "ORG"}, {"text": "Astana", "type": "LOC"}, {"text": "Kazakhstan", "type": "LOC"}, {"text": "July 5, 2018", "type": "TIME"}, {"text": "20 May 2015", "type": "TIME"}, {"text": "Republic of Kazakhstan", "type": "LOC"}, {"text": "Nursultan Nazarbayev", "type": "PER"}, {"text": "“ 100 Concrete Steps ” Plan of the Nation", "type": "MISC"}, {"text": "five", "type": "NUM"}, {"text": "30", "type": "NUM"}, {"text": "2050", "type": "TIME"}, {"text": "Plan of the Nation", "type": "MISC"}, {"text": "EXPO-2017 International Specialized Exhibition", "type": "MISC"}, {"text": "Constitutional Law", "type": "MISC"}, {"text": "On the Astana International Financial 